blobs.6fd0abf624e9:
// A live Strudel (TidalCycles-in-JS) pattern, linked by the "pad" and "kit" tracks.
// The engine plays it on them while the transport rolls, locked to the beat — edit +
// save to hear it change live.
//
// `.label(...)` names the lane a part plays on. A label matching a strudel track's
// name lands there — "Pad" on the "pad" track, so it plays through that track's chain
// and mixer strip. A label no track declares still plays, on the file's first track by
// name ("kit"); so does an unlabelled part.
//
// What `s(...)` means is the event's business: a name found as a sample — in your
// project's `samples/` folder, $DIRT_SAMPLES or $STRUDEL_SAMPLES — is a one-shot,
// anything else is a note for the lane's instrument ("sawtooth" on "pad").
stack(
  note("c e g c5").s("sawtooth").slow(2).label("Pad"),
  sound("bd hh sn hh").label("Kit"),
)

blobs.7ba905596fc2:
// synth-pad — a second use of the same "synth" module (see lead.k7x beside this file).
//
// Named for the lane it serves rather than after it: the lane "pad" is a node too now
// (nodes/pad.k7x), and one flat name space means one name, one node.
//
// Two nodes of one module are two separate chain steps with separate state: their
// params are merged independently over the module, and each saves its own opaque plugin
// blob (synth-pad.vstpreset here, lead.vstpreset next door), so tweaking one never touches
// the other or the module they share.
extends("@workspace/instruments/synth")
params({
  "Filter Freq": 40, // darker than the lead…
  Level: -12, // …and sitting further back
})
// Params merge per key, but a LIST is a scalar to the merge: restating `automations`
// replaces the inherited one outright. An empty list is how a node opts out of the
// filter sweep + detune LFO the module automates — the pad wants to sit still.
automations([])

blobs.8e9895b6a73f:
// turntableA — one @k7-core/turntable. Its members are ordinary nodes; this file is what draws them as a box.
uses("@k7-core/turntable")
members({ fade: "turntableA_fade" })

blobs.b5b3fd732b57:
// turntableA — one @k7-core/turntable. Its members are ordinary nodes; this file is what draws them as a box.
uses("@k7-core/turntable")
members({ deck: "turntableA_deck", fade: "turntableA_fade" })

blobs.b76a595a734c:
// lead — one USE of the "synth" module.
//
// A node is a `<name>.k7x` in the project's flat `nodes/` folder, and the FILE
// NAMES IT: chains say "lead" (see chains.k7x). It does not sit under the module it uses
// and does not mirror its folders — which module it uses is what `extends` says, and that
// is the only place the relationship is written down.
//
// So state only what THIS voice changes — the 4OSC plugin, the UI and the two automation
// curves all come from the synth module (which in turn extends @workspace/instruments/fourosc).
// The merge order is: fourosc -> synth -> this file, each winning per key.
extends("@workspace/instruments/synth")
params({
  "Filter Freq": 90, // brighter than the shared default — this one has to cut through
})

blobs.b84cd02f757d:
// A hand-drawn filter sweep, read 0..1: up across bar 1, held through bar 2, then
// back down by the top of bar 4.

type("custom")
points([
  time("1:1:1").value(0),
  time("2:1:1").value(1),
  time("4:1:1").value(0.25),
])

blobs.ebc74af3ff99:
// The signal graph, as SEGMENTS: each module says where its signal goes next. The chains are
// DERIVED by following the arrows — a run breaks where the signal splits, and where two signals
// meet (which is what a bus is).
//
// The LANES are here too ("melody", "pad"): a lane is a module like any other, and a run is
// named after the lane that starts it. One map, one name space — which is why the pad's synth
// is "synth-pad" rather than sharing its lane's name.
//
// `bypassed` lists the modules the signal passes through untouched, and on a lane — which
// produces rather than passes — that is its mute.

// A lane offers TWO outputs, `audio` and `midi`, and is not typed by what it holds — so the
// key names the one a run leaves by whenever there is anything to say. "melody" holds only
// sequences, so its bare key is unambiguous; "pad" streams from a pattern and holds nothing
// until the transport rolls, so nothing but this line can say its events are notes for the
// synth. See packages/song/docs/trackModules.md.

// `MIX` is the mixer's sum and `OUT` is the interface; the run between them is the MASTER
// CHAIN, and `OUT` carries the song's output level as its `Volume`. Name a module on that
// line and it processes both lanes together on the way out.

modules({
  melody: ["lead"],
  "pad#midi": ["synth-pad"],
  lead: ["MIX"],
  synth-pad: ["MIX"],
  MIX: ["OUT"],
})

